1	package world
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"syscall"
8	)
9	
10	// Record 是一次成功保存留下的、可供读取的记录。
11	type Record struct {
12		// ID 是记录标识。
13		ID RecordID
14		// Parent 是父记录标识；槽首条记录为空。
15		Parent RecordID
16		// SlotFirst 表示这是其所在槽的首条记录。
17		SlotFirst bool
18		// State 是记录保存时的完整世界数据（深拷贝，修改不影响存档）。
19		State State
20	}
21	
22	func acquireSharedLock(dir string) (*fileLock, error) {
23		path := dir + "/lock"
24		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
25		if err != nil {
26			return nil, err
27		}
28		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
29			f.Close()
30			return nil, err
31		}
32		return &fileLock{f: f}, nil
33	}
34	
35	// loadAndVerifyLocked 读取记录文件，校验其内容校验和（校验和已包含
36	// 父记录关系）、父记录是否存在，以及世界数据是否自洽。
37	//
38	// 对完整世界状态的认可与 WorldFromState 重建世界保持一致：时间片为负的
39	// 记录属于损坏记录——内容校验和匹配只说明内容完整，规则版本被接受也不
40	// 能使负时间片合法；这样的记录不能被读回，也不能作为恢复或分支的来源。
41	func (a *Archive) loadAndVerifyLocked(id RecordID) (*envelope, error) {
42		env, err := loadRecord(recordPath(a.dir, id))
43		if err != nil {
44			if errors.Is(err, os.ErrNotExist) {
45				return nil, &NotFoundError{Record: id}
46			}
47			return nil, &CorruptError{Record: id, Reason: err.Error()}
48		}
49		if env.ID != id {
50			return nil, &CorruptError{Record: id, Reason: "记录标识与文件名不一致"}
51		}
52		if got := computeChecksum(env); got != env.Checksum {
53			return nil, &CorruptError{Record: id, Reason: "内容校验和不匹配（可能已损坏或被改动）"}
54		}
55		// 父记录关系必须落到一个真实存在的记录上。
56		if env.Parent != "" {
57			if _, err := os.Stat(recordPath(a.dir, env.Parent)); err != nil {
58				if errors.Is(err, os.ErrNotExist) {
59					return nil, &CorruptError{Record: id, Reason: "父记录缺失: " + string(env.Parent)}
60				}
61				return nil, err
62			}
63		}
64		// 时间片为负的记录与 WorldFromState 的拒绝保持一致：即使校验和匹配、
65		// 其余状态合法，也按损坏处理，不自动把时间改成零。
66		if env.State.Time < 0 {
67			return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("记录中的时间片为负: %d", env.State.Time)}
68		}
69		if err := validateInitialData(InitialData{
70			Seed:       env.State.Seed,
71			Rules:      env.State.Rules,
72			Characters: env.State.Characters,
73		}); err != nil {
74			return nil, &CorruptError{Record: id, Reason: "记录中的世界数据不合法: " + err.Error()}
75		}
76		return env, nil
77	}
78	
79	func versionAccepted(version string, accepted []string) bool {
80		for _, v := range accepted {
81			if v == version {
82				return true
83			}
84		}
85		return false
86	}
87	
88	func envToRecord(env *envelope) Record {
89		return Record{
90			ID:        env.ID,
91			Parent:    env.Parent,
92			SlotFirst: env.SlotFirst,
93			State:     cloneState(env.State),
94		}
95	}
96	
97	// Latest 读取槽当前最新记录。
98	//
99	// acceptedVersions 是调用方明确给出的可接受规则版本集合：记录完好但
100	// 版本不在集合内时返回 *VersionRejectedError；记录损坏（校验和不符、
101	// 父记录缺失、无法解析、时间片为负）时返回 *CorruptError。读取不会改写存档。
102	func (a *Archive) Latest(slot string, acceptedVersions []string) (Record, error) {
103		if !validSlotName(slot) {
104			return Record{}, &NotFoundError{Slot: slot}
105		}
106		lock, err := acquireSharedLock(a.dir)
107		if err != nil {
108			return Record{}, err
109		}
110		defer lock.release()
111	
112		id, err := a.readLatestLocked(slot)
113		if err != nil {
114			return Record{}, err
115		}
116		env, err := a.loadAndVerifyLocked(id)
117		if err != nil {
118			if ce, ok := err.(*CorruptError); ok {
119				ce.Slot = slot
120			}
121			return Record{}, err
122		}
123		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
124			return Record{}, &VersionRejectedError{
125				Slot:     slot,
126				Record:   id,
127				Version:  env.State.Rules.Version,
128				Accepted: append([]string(nil), acceptedVersions...),
129			}
130		}
131		return envToRecord(env), nil
132	}
133	
134	// Record 按标识读取槽的一份历史记录（覆盖后的旧记录仍可读取）。
135	//
136	// 与 Latest 一样检查内容校验和（含父记录关系）与规则版本，且记录必须
137	// 属于该槽的历史链。读取不会改写存档，也不会改变规则版本。
138	func (a *Archive) Record(slot string, id RecordID, acceptedVersions []string) (Record, error) {
139		if !validSlotName(slot) {
140			return Record{}, &NotFoundError{Slot: slot}
141		}
142		lock, err := acquireSharedLock(a.dir)
143		if err != nil {
144			return Record{}, err
145		}
146		defer lock.release()
147	
148		if err := a.assertInSlotHistoryLocked(slot, id); err != nil {
149			return Record{}, err
150		}
151		env, err := a.loadAndVerifyLocked(id)
152		if err != nil {
153			if ce, ok := err.(*CorruptError); ok {
154				ce.Slot = slot
155			}
156			return Record{}, err
157		}
158		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
159			return Record{}, &VersionRejectedError{
160				Slot:     slot,
161				Record:   id,
162				Version:  env.State.Rules.Version,
163				Accepted: append([]string(nil), acceptedVersions...),
164			}
165		}
166		return envToRecord(env), nil
167	}
168	
169	// History 返回槽的历史记录元信息，按该槽保存生效的次序排列（最新在
170	// 前），到槽首条记录为止；分支槽只含它自己保存成功的记录，不会跨入
171	// 分支来源槽。次序来自槽指针内嵌的历史索引，与文件修改时间无关。该
172	// 方法只做只读遍历，不改写任何数据；无法解析的记录会被略过。
173	func (a *Archive) History(slot string) ([]RecordInfo, error) {
174		if !validSlotName(slot) {
175			return nil, &NotFoundError{Slot: slot}
176		}
177		lock, err := acquireSharedLock(a.dir)
178		if err != nil {
179			return nil, err
180		}
181		defer lock.release()
182	
183		history, err := a.slotHistoryLocked(slot)
184		if err != nil {
185			return nil, err
186		}
187		infos := make([]RecordInfo, 0, len(history))
188		for _, id := range history {
189			env, err := loadRecord(recordPath(a.dir, id))
190			if err != nil {
191				continue
192			}
193			infos = append(infos, RecordInfo{
194				ID:        env.ID,
195				Parent:    env.Parent,
196				SlotFirst: env.SlotFirst,
197				Version:   env.State.Rules.Version,
198			})
199		}
200		return infos, nil
201	}
202	
203	// RecoverLatest 返回该槽“按保存生效次序最近的一份”内容校验通过且规则
204	// 版本可接受的已保存记录。
205	//
206	// 遍历次序完全来自槽指针维护的历史索引（最新在前），既不依据文件修改
207	// 时间，也不读取受损记录里的父标识或槽首标记：因此最新记录被删除、
208	// 截断成无法解析的内容，或连同若干中间记录一起损坏时，仍能越过它们
209	// 找到本槽更早的可用记录，而不会被引向别的槽或遮住更早的可用记录。遍历
210	// 次序与世界时间片的大小无关；时间片为负的记录属于损坏记录，同样被越过。
211	//
212	// 分支槽只在分支自身已成功保存的记录中查找；即使分支首条记录损坏也不
213	// 越过分支边界，其他槽即使种子和规则相同也不会替代。版本不被接受的
214	// 记录一律跳过且不自动升级。只有记录文件写完且指针已更新（即保存完整
215	// 生效）的记录才在候选中：残留临时文件、写完但尚未完成保存的孤儿记录
216	// 不会被选中。
217	//
218	// 槽不存在返回 *NotFoundError；槽指针不可读返回 *CorruptError；槽中没有
219	// 任何版本可接受的完好记录时返回包装了 ErrUnrecoverable 的
220	// *UnrecoverableError，可用 errors.Is(err, ErrUnrecoverable) 判断。
221	// 恢复读取不会改写槽、指针、历史记录或规则，重复读取也不消耗历史。
222	func (a *Archive) RecoverLatest(slot string, acceptedVersions []string) (Record, error) {
223		if !validSlotName(slot) {
224			return Record{}, &NotFoundError{Slot: slot}
225		}
226		lock, err := acquireSharedLock(a.dir)
227		if err != nil {
228			return Record{}, err
229		}
230		defer lock.release()
231	
232		history, err := a.slotHistoryLocked(slot)
233		if err != nil {
234			return Record{}, err
235		}
236	
237		env, err := a.firstRecoverableLocked(history, acceptedVersions)
238		if err != nil {
239			var ue *UnrecoverableError
240			if errors.As(err, &ue) {
241				ue.Slot = slot
242			}
243			return Record{}, err
244		}
245		return envToRecord(env), nil
246	}
247	
248	// firstRecoverableLocked 在调用方已持锁的前提下，按给定的保存生效次序
249	// （最新在前）返回第一份“内容与父关系校验通过且规则版本可接受”的记录。
250	//
251	// 文件缺失、截断、校验和不符、记录标识不符、父关系异常、时间片为负或世界
252	// 状态不自洽的记录一律越过（不读其中的父标识或槽首标记）；版本不被接受的
253	// 记录也越过且不自动升级。次序完全由调用方给出（来自槽指针历史索引或沿可信
254	// 父链的重建），因此不会被引向别的槽。没有任何可用记录时返回包装了
255	// ErrUnrecoverable 的 *UnrecoverableError（Slot 字段由调用方补全）。
256	func (a *Archive) firstRecoverableLocked(history []RecordID, acceptedVersions []string) (*envelope, error) {
257		var lastReason string
258		for _, id := range history {
259			env, verifyErr := a.loadAndVerifyLocked(id)
260			if verifyErr != nil {
261				lastReason = verifyErr.Error()
262				continue
263			}
264			if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
265				lastReason = (&VersionRejectedError{
266					Record:  id,
267					Version: env.State.Rules.Version,
268				}).Error()
269				continue
270			}
271			return env, nil
272		}
273	
274		if lastReason == "" {
275			lastReason = "槽中没有任何可确认归属的历史记录"
276		}
277		return nil, &UnrecoverableError{Reason: lastReason}
278	}
279

