12	// TestMain 支持以子进程方式运行多进程并发测试。
13	func TestMain(m *testing.M) {
14		switch os.Getenv("WORLD_TEST_HELPER") {
15		case "":
16			os.Exit(m.Run())
17		case "concurrent_replace":
18			helperConcurrentReplace()
19			os.Exit(0)
20		case "generate_world":
21			helperGenerateWorld()
22			os.Exit(0)
23		default:
24			fmt.Fprintln(os.Stderr, "unknown helper")
25			os.Exit(2)
26		}
27	}
28	
29	func newTestArchive(t *testing.T) (*Archive, string) {
30		t.Helper()
31		dir := t.TempDir()
32		a, err := Create(dir)
33		if err != nil {
34			t.Fatalf("Create: %v", err)
35		}
36		return a, dir
37	}
