40		a, _ := newTestArchive(t)
41		w := baseWorld(t)
42		if _, err := a.Save("slot1", w); err != nil {
43			t.Fatal(err)
44		}
45		_, err := a.Save("slot1", w)
46		var ce *ConflictError
47		if !errors.As(err, &ce) {
48			t.Fatalf("重名应返回 ConflictError，得到 %T: %v", err, err)
49		}
50	}
