86			t.Fatal("用过时标识覆盖应冲突")
87		} else {
88			var ce *ConflictError
89			if !errors.As(err, &ce) {
90				t.Fatalf("应返回 ConflictError，得到 %T", err)
91			}
92		}
93	}
