100			t.Fatal(err)
101		}
102		for i := 1; i <= 3; i++ {
103			if _, err := w.Apply(Commit{Time: i}); err != nil {
104				t.Fatal(err)
105			}
106			latest, err := a.Latest("s", []string{"v1"})
107			if err != nil {
108				t.Fatal(err)
109			}
110			if _, err := a.Replace("s", w, latest.ID); err != nil {
111				t.Fatal(err)
112			}
113		}
114	
115		// 重新打开目录后，最早的记录仍可按标识读取，父关系仍在。
116		a2, err := Open(dir)
117		if err != nil {
