121		if err != nil {
122			t.Fatalf("读取覆盖前的历史记录: %v", err)
123		}
124		if rec.State.Time != 0 || !rec.SlotFirst || rec.Parent != "" {
125			t.Fatalf("首条记录关系错误: %+v", rec)
126		}
127		if rec.State.Seed != 42 {
128			t.Fatal("历史记录应完整保存种子")
129		}
130		hist, err := a2.History("s")
131		if err != nil {
