207	func TestReadVersionAndCorruptionRecovery(t *testing.T) {
208		a, dir := newTestArchive(t)
209		w := baseWorld(t)
210		r0, _ := a.Save("s", w)
211		cur, _ := a.Latest("s", []string{"v1"})
212		_, _ = w.Apply(Commit{Time: 1})
213		r1, _ := a.Replace("s", w, cur.ID)
214	
215		// 版本集合不含任何匹配版本 -> 明确拒绝，且不改写。
216		if _, err := a.Latest("s", []string{"v9"}); err == nil {
217			t.Fatal("版本不被接受应返回错误")
218		} else {
219			var vre *VersionRejectedError
220			if !errors.As(err, &vre) {
221				t.Fatalf("应返回 VersionRejectedError，得到 %T", err)
222			}
223		}
224	
225		// 直接写一条 v2 的最新记录（读取侧永远不能替换记录中的规则，
226		// 这里模拟由其他兼容版本写入器产生的数据）。
227		v2State := w.Snapshot()
228		v2State.Time = 2
229		v2State.Rules.Version = "v2"
230		r2 := writeRawRecord(t, a, r1.ID, false, v2State)
231		updatePointer(t, a, "s", r2)
232	
233		// Latest 在仅接受 v1 时拒绝最新记录；恢复读取应越过 v2 找到 r1。
234		if _, err := a.Latest("s", []string{"v1"}); err == nil {
235			t.Fatal("v2 最新记录应被版本拒绝")
236		}
237		rec, err := a.RecoverLatest("s", []string{"v1"})
238		if err != nil {
239			t.Fatalf("应恢复到 v1 历史记录: %v", err)
240		}
241		if rec.ID != r1.ID {
242			t.Fatalf("应恢复到最近可接受记录 %s，得到 %s", r1.ID, rec.ID)
243		}
244		// 恢复读取不改写槽指针与历史。
245		ptr, err := a.readLatestLocked("s")
246		if err != nil {
247			t.Fatal(err)
248		}
249		if ptr != r2 {
250			t.Fatal("恢复读取改写了槽指针")
251		}
252	
253		// 损坏最新记录：改写其校验和（JSON 仍可解析，父指针仍在）。
254		// Latest 报损坏；恢复应越过它，沿父指针找到可接受记录。
255		{
256			path := recordPath(dir, r2)
257			raw, err := os.ReadFile(path)
258			if err != nil {
259				t.Fatal(err)
260			}
261			s := string(raw)
262			i := strings.Index(s, `"checksum": "`)
263			if i < 0 {
264				t.Fatal("找不到 checksum 字段")
265			}
266			start := i + len(`"checksum": "`)
267			end := start + 64
268			s = s[:start] + strings.Repeat("0", 64) + s[end:]
269			if err := os.WriteFile(path, []byte(s), 0o600); err != nil {
270				t.Fatal(err)
271			}
272		}
273		if _, err := a.Latest("s", []string{"v1", "v2"}); err == nil {
274			t.Fatal("损坏记录应报错")
275		} else {
276			var ce *CorruptError
277			if !errors.As(err, &ce) {
278				t.Fatalf("应返回 CorruptError，得到 %T", err)
279			}
280		}
281		rec2, err := a.RecoverLatest("s", []string{"v1"})
282		if err != nil {
283			t.Fatalf("应越过损坏记录恢复: %v", err)
284		}
285		if rec2.ID != r1.ID {
286			t.Fatalf("恢复结果错误: %s", rec2.ID)
287		}
288	
289		// 连最后可接受的根也不可接受时 -> 不可恢复。
290		_, err = a.RecoverLatest("s", []string{"v9"})
291		if !errors.Is(err, ErrUnrecoverable) {
292			t.Fatalf("应返回 ErrUnrecoverable，得到 %T: %v", err, err)
293		}
294	
295		// r0 仍完好且可按标识读取（在进一步截断链之前）。
296		r0rec, err := a.Record("s", r0.ID, []string{"v1"})
297		if err != nil {
298			t.Fatal(err)
299		}
300		if r0rec.ID != r0.ID {
301			t.Fatal("根记录读取错误")
302		}
303	
304		// 最新记录被截断到无法解析时，历史索引仍保留保存次序，恢复应越过
305		// 它找到更早的可用记录（不能因为读不出父标识就放弃）。
306		if err := os.Truncate(recordPath(dir, r2), 40); err != nil {
307			t.Fatal(err)
308		}
309		rec3, err := a.RecoverLatest("s", []string{"v1"})
310		if err != nil {
311			t.Fatalf("最新记录被截断成无法解析的内容时仍应恢复到更早记录: %v", err)
312		}
313		if rec3.ID != r1.ID {
314			t.Fatalf("应越过被截断的最新记录恢复到 %s，得到 %s", r1.ID, rec3.ID)
315		}
316		// 重新打开存档后结果一致。
317		a3, err := Open(dir)
318		if err != nil {
319			t.Fatal(err)
320		}
321		rec4, err := a3.RecoverLatest("s", []string{"v1"})
322		if err != nil {
323			t.Fatalf("重开后恢复结果不一致: %v", err)
324		}
325		if rec4.ID != r1.ID {
326			t.Fatalf("重开后应恢复到 %s，得到 %s", r1.ID, rec4.ID)
327		}
328	}
