458	// writeRawRecord 直接写入一条记录文件并返回其标识，供损坏/版本测试使用。
459	func writeRawRecord(t *testing.T, a *Archive, parent RecordID, first bool, st State) RecordID {
460		t.Helper()
461		id, err := newRecordID()
462		if err != nil {
463			t.Fatal(err)
464		}
465		env := &envelope{
466			Format:    archiveFormatVersion,
467			ID:        id,
468			Parent:    parent,
469			SlotFirst: first,
470			State:     st,
471		}
472		env.Checksum = computeChecksum(env)
473		if err := writeRecord(a.dir, env); err != nil {
474			t.Fatal(err)
475		}
476		return id
477	}
