479	// updatePointer 模拟一个遵循磁盘格式的写入器：新记录已完整落盘后原子
480	// 更新槽指针，并把新记录按保存次序前置到历史索引。
481	func updatePointer(t *testing.T, a *Archive, slot string, id RecordID) {
482		t.Helper()
483		lock, err := acquireLock(a.dir)
484		if err != nil {
485			t.Fatal(err)
486		}
487		defer lock.release()
488		old, err := a.readSlotPointerLocked(slot)
489		if err != nil {
490			t.Fatal(err)
491		}
492		history := []RecordID{id}
493		for _, hid := range old.History {
494			if hid != id {
495				history = append(history, hid)
496			}
497		}
498		if err := a.persistSlotPointerLocked(slot, slotPointer{Latest: id, History: history}); err != nil {
499			t.Fatal(err)
500		}
501	}
