		if hist[i].ID != wantHist[i] {
			t.Fatalf("历史次序错误: %+v，期望 %v", hist, wantHist)
		}
	}

	// 来源之后仍完好的旧记录可照常读取；从它分出新分支也不受影响。
	old, err := a.Record("s", r0.ID, []string{"v1"})
