383		for i := 0; i < 2; i++ { // 重复读取不消耗历史
384			rec, err := a.RecoverLatest("s", []string{"v1"})
385			if err != nil {
386				t.Fatalf("残留/孤儿不应影响恢复: %v", err)
387			}
388			if rec.ID != r0.ID {
389				t.Fatalf("残留或孤儿记录被选中: 得到 %s，应为 %s（孤儿 %s）", rec.ID, r0.ID, orphan)
390			}
391		}
