394	// TestRecoverUpgradeChain 升级产生的记录同样支持恢复：升级后最新记录损坏
395	// 时，只接受旧版本的恢复读取找到升级前记录；新旧版本都接受时找到升级后
396	// 之前最近的完好记录。
397	func TestRecoverUpgradeChain(t *testing.T) {
398		a, dir := newTestArchive(t)
