421	// TestRecoverDoesNotMutate 恢复读取不修改目录内容：槽指针文件字节、records
422	// 目录条目集合在多次恢复前后保持一致；不修补损坏记录、不改槽当前记录。
423	func TestRecoverDoesNotMutate(t *testing.T) {
424		a, dir := newTestArchive(t)
425		ids := saveN(t, a, "s", 3)
426		corruptChecksum(t, dir, ids[0])
427		truncateRecord(t, dir, ids[1])
428	
429		snapshot := func() (string, map[string]int64) {
430			ptr, err := os.ReadFile(a.slotPath("s"))
431			if err != nil {
432				t.Fatal(err)
433			}
434			entries, err := os.ReadDir(filepath.Join(dir, recordsName))
435			if err != nil {
436				t.Fatal(err)
437			}
438			m := map[string]int64{}
439			for _, e := range entries {
440				fi, err := e.Info()
441				if err != nil {
442					t.Fatal(err)
443				}
444				m[e.Name()] = fi.Size()
445			}
446			return string(ptr), m
447		}
448	
449		ptrBefore, filesBefore := snapshot()
450		if _, err := a.RecoverLatest("s", []string{"v1"}); err != nil {
451			t.Fatal(err)
452		}
453		if _, err := a.RecoverLatest("s", []string{"v1"}); err != nil {
454			t.Fatal(err)
455		}
456		ptrAfter, filesAfter := snapshot()
457	
458		if ptrBefore != ptrAfter {
459			t.Fatal("恢复读取改写了槽指针")
460		}
461		if len(filesBefore) != len(filesAfter) {
462			t.Fatalf("恢复读取改变了 records 目录条目数: %d -> %d", len(filesBefore), len(filesAfter))
463		}
464		for name, size := range filesBefore {
465			if filesAfter[name] != size {
466				t.Fatalf("恢复读取改动了文件 %s: %d -> %d", name, size, filesAfter[name])
467			}
468		}
469		// 槽当前记录仍是损坏的最新记录，Latest 依旧报损坏。
470		if _, err := a.Latest("s", []string{"v1"}); err == nil {
471			t.Fatal("恢复读取不应修补槽当前记录")
472		}
473	}
