694		// 新记录与中间记录同时损坏/删除，仍能恢复到旧历史里的首存记录。
695		corruptChecksum(t, dir, r3.ID)
696		deleteRecord(t, dir, ids[0])
697		truncateRecord(t, dir, ids[1])
698		rec, err := a2.RecoverLatest("s", []string{"v1"})
699		if err != nil {
700			t.Fatalf("旧历史获得恢复能力后应找到首存记录: %v", err)
701		}
702		if rec.ID != ids[2] {
703			t.Fatalf("应恢复首存记录 %s，得到 %s", ids[2], rec.ID)
