727	// TestRecoverDeletedMiddleBreaksTipParent 中间记录被删除时，最新记录自身
728	// 内容完好但父记录关系不再成立，按已有校验要求它也算受损；恢复仍应越过
729	// 它与缺失项，落到父记录仍在、自身完好的更早记录。
730	func TestRecoverDeletedMiddleBreaksTipParent(t *testing.T) {
