// assertCorruptRejected 断言覆盖返回带槽名与记录标识的 *CorruptError，且
// 不写入、不移动槽指针与历史。
func assertCorruptRejected(t *testing.T, a *Archive, slot string, id RecordID, beforeCount int, pointer slotPointer, info RecordInfo, err error) {
